///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearchCorpName
 * @description fn Search Corp Name 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearchCorpName = async function () {
    const sbmOptions = {
        id: "tx_fnSearchCorpName",
        method: "post",
        action: "/disclosure/searchinvestprospectus.do",
        ref: "dma_fnSearchCorpNameReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

