///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name sortBy
 * @description sort By 처리
 * @param {*} sortDiv sortDiv
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sortBy = async function (sortDiv) {
    $c.util.getComponent("sort_1").className = "";
    $c.util.getComponent("sort_2").className = "";
    if (sortDiv === "1") {
        $c.util.getComponent("sort_1").className = "on";
    } else {
        $c.util.getComponent("sort_2").className = "on";
    }
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('orderIndex', sortDiv);
    await scwin.fncSearch();
};

/**
 * @method
 * @name corpType
 * @description corp Type 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.corpType = function (val) {
    if ($c.num.isNumber(val.value) === true) {
        if (val.value.length < 6 || val.value.length > 7) {
            val.value = "";
            $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "");
            return false;
        } else {
            $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "number");
        }
    } else {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "char");
    }
};

/**
 * @method
 * @name fnsearchKeyCode
 * @description fnsearch Key Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnsearchKeyCode = async function () {
    // TODO Stage2(규칙19): fieldEl(DOM 요소 계약) → 컴포넌트 getValue/setValue 계약으로 전환 필요
    const obj = ($c.util.fieldEl('AKCKwd', 'searchCorpName'));
    chkValidChar(obj);
    scwin.corpType(obj);
    await scwin.fnSearchCorpName("Y");
};

/**
 * @method
 * @name fnSearchCorpName
 * @description fn Search Corp Name 처리
 * @param {*} val val
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpName = async function (val) {
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', "");
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("allRepIsuSrtCd", "");
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchMode', val);
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('method', "searchCorpName");
        (document.frm || { elements: [] }).target = "iframe_1";
        await scwin.tx_fnSearchCorpName();
    } else {
        await scwin.fncSearch();
    }
};

/**
 * @method
 * @name fnSearchCorpCode
 * @description fn Search Corp Code 처리
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpCode = async function (repIsuSrtCd) {
    if (repIsuSrtCd === "") {
        if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('searchCodeType') === "char") {
            await $c.win.alert("조회한 종목명이 존재하지 않습니다.");
            $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', "");
            return;
        } else {
            if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('searchCodeType') === "number") {
                await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
                $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', "");
                return;
            }
        }
    } else {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', repIsuSrtCd);
        await scwin.fncSearch();
    }
};

/**
 * @method
 * @name fncSearch
 * @description fnc Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fncSearch = async function () {
    if (!$c.date.isDate($c.util.getComponent('cal_fromData').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toData').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_fromData').getValue(), $c.util.getComponent('cal_toData').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('repIsuSrtCd') !== "") {
        $c.util.getComponent("dma_fnSearchCorpNameReq").set("allRepIsuSrtCd", "");
    }
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) === '') {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "");
    }
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('forward', "searchinvestmentdisclosure_sub");
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('method', "searchInvestProspectusSub");
    if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('searchMode') === "Y") {
        $c.util.getComponent("dma_fnSearchCorpNameReq").set("currentPageSize", document.iframe.document.iFrm.currentPageSize.value);
        $c.util.getComponent("dma_fnSearchCorpNameReq").set("pageIndex", "1");
    } else {
        $c.util.getComponent("dma_fnSearchCorpNameReq").set("currentPageSize", document.iframe.document.iFrm.currentPageSize.value);
        $c.util.getComponent("dma_fnSearchCorpNameReq").set("pageIndex", document.iframe.document.iFrm.pageIndex.value);
    }
    (document.frm || { elements: [] }).target = "iframe";
    await scwin.tx_fncSearch();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    if (!$c.date.isDate($c.util.getComponent('cal_fromData').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toData').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_fromData').getValue(), $c.util.getComponent('cal_toData').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    if ($c.util.getComponent('dma_fnSearchCorpNameReq').get('repIsuSrtCd') !== "") {
        $c.util.getComponent("dma_fnSearchCorpNameReq").set("allRepIsuSrtCd", "");
    }
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) === '') {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "");
    }
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('forward', "searchinvestmentdisclosure_sub");
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('method', "searchInvestProspectusSub");
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("currentPageSize", document.iframe.document.iFrm.currentPageSize.value);
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("pageIndex", document.iframe.document.iFrm.pageIndex.value);
    (document.frm || { elements: [] }).target = "iframe";
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name findCorpName
 * @description find Corp Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findCorpName = async function () {
    const wUrl = "/common/corpList.do?method=loadInitPage&comnm_tffield=AKCKwd&pMethod=null";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(wUrl), { id: '회사명찾기', width: "630", height: "510" }, {});
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuSrtCd : " + repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    $c.util.getComponent("AKCKwd").setValue(repIsuSrtCd);
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', "A" + repIsuSrtCd);
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "char");
};

/**
 * @method
 * @name download
 * @description download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.download = async function () {
    if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) === '') {
        $c.util.getComponent('dma_fnSearchCorpNameReq').set('searchCodeType', "");
    }
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("currentPageSize", document.iframe.document.iFrm.currentPageSize.value);
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("pageIndex", document.iframe.document.iFrm.pageIndex.value);
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('forward', "searchinvestmentdisclosure_down");
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('method', "searchInvestProspectusSub");
    (document.frm || { elements: [] }).target = "iframe_2";
    await scwin.tx_download();
};

/**
 * @method
 * @name clickListComp
 * @description click List Comp 처리
 * @param {*} pCode pCode
 * @param {*} pName pName
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.clickListComp = async function (pCode, pName) {
    $c.util.getComponent("AKCKwd").setValue(pName);
    await scwin.fnSearchCorpName("Y");
};

/**
 * @method
 * @name getCookieComCode
 * @description get Cookie Com Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getCookieComCode = async function () {
    const cookiesStr = scwin.GetCookie('krxComp');
    let totalArray;
    let newVal = "";
    if (cookiesStr != null) {
        totalArray = cookiesStr.split("/");
    }
    const j = 0;
    const sCookieVal = "";
    for (i = 0; j < 11 && i < totalArray.length - 1; i++) {
        const sCookieTemp = totalArray[i].split(",");
        if (i === 0) {
            newVal = newVal + "'" + sCookieTemp[1] + "'";
        } else {
            newVal = newVal + ",'" + sCookieTemp[1] + "'";
        }
    }
    $c.util.getComponent('dma_fnSearchCorpNameReq').set('repIsuSrtCd', "");
    $c.util.getComponent("dma_fnSearchCorpNameReq").set("allRepIsuSrtCd", newVal);
    await scwin.fncSearch();
};

/**
 * @method
 * @name GetCookie
 * @description Get Cookie 처리
 * @param {*} keyname keyname
 * @returns {void}
 * @hidden N
 */
scwin.GetCookie = function (keyname) { const v = $c.util.getSessionStorage(keyname); return (v === undefined || v === null) ? '' : v; };

/**
 * @method
 * @name setTime
 * @description set Time 처리
 * @returns {void}
 * @hidden N
 */
scwin.setTime = function () {
    const vCurDate = $c.date.formatDate("yyyy-mm-dd hh:mm:ss");
    txb_now.setValue("현재시각 : " + vCurDate);
    runClock();
};
